import pathlib
ROOT = pathlib.Path('/Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature')

# scandir carries its OWN wording, not the shared CHECK_NULL_PATH one.
p = ROOT / 'src/codegen/lower_inst/builtins/io.rs'
t = p.read_text()
old = '''pub(super) const EMPTY_PATH_MESSAGE: &str = "Path must not be empty";'''
new = '''pub(super) const EMPTY_PATH_MESSAGE: &str = "Path must not be empty";

/// `scandir()`'s own empty-directory wording, which is NOT the shared one.
///
/// MEASURED: php prints `scandir(): Argument #1 ($directory) must not be empty` here, while the
/// openers print the bare `Path must not be empty`. Reusing the shared message would be a
/// plausible-looking lie that no test comparing against php would forgive.
pub(super) const SCANDIR_EMPTY_PATH_MESSAGE: &str =
    "scandir(): Argument #1 ($directory) must not be empty";'''
assert t.count(old) == 1
p.write_text(t.replace(old, new, 1))
print('io.rs: scandir wording')

p = ROOT / 'src/codegen/lower_inst/builtins/io/filesystem_ops.rs'
t = p.read_text()
old = '''    super::super::ensure_arg_count_between(inst, "scandir", 1, 3)?;
    let path = expect_operand(inst, 0)?;
    load_string_to_result(ctx, path, "scandir")?;'''
new = '''    super::super::ensure_arg_count_between(inst, "scandir", 1, 3)?;
    let path = expect_operand(inst, 0)?;
    // php throws for an empty directory name, in wording of its own — see the constant.
    super::emit_empty_path_value_error(ctx, path, super::SCANDIR_EMPTY_PATH_MESSAGE)?;
    load_string_to_result(ctx, path, "scandir")?;'''
assert t.count(old) == 1
p.write_text(t.replace(old, new, 1))
